[94413] = {"Магическое оскорбление", {"Убейте 6 провидцев-новичков Ваятелей ветра на Шен'дарском нагорье."}},
[94414] = {"Якори Зефриса", {"Поговорите с Халааном Орлиный Глаз и разделите его дар, чтобы взглянуть на опорный столп вдалеке."}},
[94427] = {"Урок благочестия", {"Поговорите с Танис Элдервуд в Подгороде."}},
