[94435] = {"Урок благочестия", {"Вернитесь к Даните Морр в крепость Бандариона."}},
[94436] = {"Урок благочестия", {"Поговорите со стражем смерти Билмутом в крепости Бандариона.","","Если вы потеряете знак Жизни, вернитесь к Даните Морр, чтобы получить новый."}},
[94438] = {"Урок благочестия", {"Возьмите знак Жизни и с его помощью воскресите стража смерти Фалгана в Долине ядовитых пауков.","","Если вы потеряете знак Жизни, вернитесь к Даните Морр, чтобы получить новый."}},
[94440] = {"Урок благочестия", {"Добудьте планы атаки Алого ордена у алых крестоносцев в Долине ядовитых пауков и отнесите стражу смерти Билмуту в крепость Бандариона."}},
[94441] = {"Урок благочестия", {"Поговорите с Данитой Морр в главном зале крепости Бандариона."}},
[94449] = {"Зов Огня", {"Найдите Брюкса Дитя Искр в Дун Мороге."}},
[94465] = {"Зов Огня", {"Отнесите факел Дремлющего Пламени Бралдиру Пеплоплащу в Лок Модане."}},
[94466] = {"Зов Огня", {"Принесите 1 порцию огненной смолы и 1 мешочек с реагентами Бралдиру Пеплоплащу в Лок Модане."}},
[94467] = {"Зов Огня", {"Победите низшее воплощение огня и поместите светящийся уголек в жаровню в святилище Неугасимого Пламени."}},
[94468] = {"Зов Огня", {"Принесите факел Вечного Пламени Брюксу Дитя Искр в Дун Морог."}},
