[94473] = {"Сапта огня", nil},
[94480] = {"Подарок от врагов", {"Доставьте украденный корм Горгу в Рог'мар."}},
[94481] = {"Порция силы", {"Накормите 8 |4рог'марского новобранца:рог'марских новобранцев:рог'марских новобранцев; на тренировочной площадке."}},
[94483] = {"Покажи им, как надо", {"Убейте 8 |4фархолдского жреца:фархолдских жрецов:фархолдских жрецов; и 12 |4фархолдского разведчика:фархолдских разведчиков:фархолдских разведчиков; к югу от реки."}},
[94484] = {"Тревожное молчание", {"Отыщите Элегаэль Колючую Лапу в северо-восточной части Теневейного леса."}},
[94485] = {"Девичьи слезы", {"Соберите 8 |4порцию:порции:порций; мха \"Девичьи слезы\"."}},
[94486] = {"Перья для перевязки", {"Добудьте 20 |4перо:пера:перьев; теневейных визгунов в Теневейном лесу."}},
[94487] = {"Ненужные и недостойные", {"Добудьте 10 |4окровавленную фамильную реликвию:окровавленные фамильные реликвии:окровавленных фамильных реликвий; у ал'акетских пехотинцев и ал'акетских ловцов бурь в Теневейном лесу."}},
[94488] = {"Неразрывные узы", {"Убейте командира Хаалиена и принесите его голову Элегаэль Колючей Лапе в Теневейном лесу."}},
[94489] = {"Раны предательства", {"Войдите в логово Клыка Ночи, исцелите 7 |4друида:друидов:друидов; и найдите Йорела Песнь Ветра в Теневейном лесу."}},
