[96655] = {"Основы походной жизни: кулинария", {"Поговорите с поваром Торкой в Колючем Холме, чтобы стать поваром."}},
[96656] = {"В поисках приключений", {"Поговорите с Элеанор Шеклтон возле Брилла."}},
[96658] = {"Основы походной жизни: кулинария", {"Поговорите с Вильямом Пикманом в Брилле, чтобы стать поваром."}},
[96659] = {"В поисках приключений", {"Доставьте сверток с припасами Каге Дикое Копыто рядом с деревней Кровавого Копыта."}},
[96661] = {"Основы походной жизни: кулинария", {"Поговорите с Пиаллом Тихая Поступь в деревне Кровавого Копыта, чтобы стать поваром."}},
[96770] = {"Голова знахаря", {"Убейте знахаря Зум'ру и принесите голову Зум'ры верховному магу Лан'далоку в Даларан."}},
[96771] = {"Отмщение высокорожденного", {"Отправьтесь в крепость Крол'док и убейте Залфана Тень Луны."}},
[96773] = {"Око Хладовея", {"Раздобудьте Око Хладовея в курганах Иглошкурых."}},
[96774] = {"Идол древней империи Гурубаши", {"Достаньте идола древней империи Гурубаши из затонувшего города."}},
[96775] = {"Голова Зум'ры", {"Убейте знахаря Зум'ру и принесите голову Зум'ры Мазу'кону в Мулгор."}},
[96776] = {"Сияние Ан'ше", {"Раздобудьте в Мародоне кристалл, известный как \"Сияние Ан'ше\"."}},
[96779] = {"Саботаж Синдиката", {"Найдите лорда Томаса в крепости Дарнхольд в предгорьях Хилсбрада и убейте его. Затем вернитесь к Мирокосу Тихоступу."}},
[96781] = {"Что за дела?", {"Выкрадите у Бартона отчет разведки, затем принесите его Мирокосу Тихоступу в поместье Черного Ворона."}},
[96782] = {"Тайное изъятие", {"Найдите клинок дома Перенольдов и королевскую эгиду дома Перенольдов в руинах Альтерака. Затем принесите их Мирокосу Тихоступу."}},
[96783] = {"Путь проникновения", {"Украдите форму Синдиката в Северном поместье, чтобы проникнуть в крепость Стромгард."}},
[96784] = {"Мастер перевоплощения", {"Переодевшись в члена Синдиката, найдите кого-нибудь в крепости Стромгард, кто знает о тайной встрече."}},
[96785] = {"Ничего не скажу", {"Найдите в крепости Стромгард что-нибудь, что заставит Анастасию поделиться подробностями о тайной встрече."}},
[96786] = {"Засада на Синдикат", {"Помешайте тайной встрече и заберите предмет, который на ней должны передать Синдикату. Затем вернитесь к Мирокосу Тихоступу."}},
[96800] = {"Запоздалая расплата", {"Принесите книгу \"Утерянная магия мастеров рун\" из монастыря Алого ордена."}},
[96821] = {"Слишком много ног", {"Убейте 6 темногорных ползунов и 6 темногорных скрытней в южном Дуротаре и сообщите об этом Га'Току в Колючем Холме."}},
[96822] = {"За честь", {"Добудьте разбойничий боевой топор, разбойничий лук и разбойничий щит на задворках крепости Тирагард, а затем принесите их Турроку в Колючий Холм."}},
[96825] = {"Кусачий фрукт", {"Соберите 8 колючих груш в землях Иглогривых на западе от Колючего Холма для повара Торки."}},
[96873] = {"Подчиняющие подвески", {"Добудьте 3 порции светящегося осадка для Па'зулы из деревни Сен'джин. Светящийся осадок можно получить, распылив проклятые подвески, добытые у троллей на островах Эха."}},
[96874] = {"Спинной рассекатель", {"Добудьте 5 иссохших хребтов у зверей на Громовом хребте и 5 грубых шлифовальных камней для Уг'тока в Оргриммаре."}},
[96875] = {"Звери Громового хребта", {"Добудьте 5 грубых шкур ящерицы у зверей на Громовом хребте, а также 2 обработанные легкие шкуры, для Камари из Оргриммара."}},
[96876] = {"Потерянная сума Укора", {"Верните сумку Укору в южном Дуротаре."}},
[96877] = {"Копыто Галикора", {"Отнесите копыто Галикора в Оргриммар."}},
[96895] = {"Посланник ордена Серебряного Рассвета", {"Найдите агента ордена Серебряного Рассвета у входа в Подгород."}},
[96896] = {"Правое дело", {"Послушайте разговор Даниты Морр и Леонида Барталомея Чтимого."}},
[96897] = {"Культ Проклятых", {"Убейте 8 |4темного неофита:темных неофитов:темных неофитов; и 8 |4карателя:карателей:карателей; Тьмы в Тирисфальских лесах."}},
[96898] = {"Пережитки войны", {"Соберите 12 |4осколок:осколка;осколков; некротического кристалла в Тирисфальских лесах."}},
[96899] = {"Крепость Бандариона", {"Встретьтесь с Леонидом Бартоломеем в крепости Бандариона в Тирисфальских лесах."}},
[96984] = {"Источник сбоя", {"Добудьте частицу чар по просьбе волхва Вурдена Сиянье Бездны на Мельнице Таррен."}},
[96986] = {"Могильный рыцарь", {"Победите в Даларане Атрексия Могильного Рыцаря по просьбе Мелизары с Мельницы Таррены."}},
[96987] = {"Обучение на работе", {"Найдите в Даларане \"Основание Даларана\" и принесите Рекси Меднохватьс к входу в канализацию."}},
[96988] = {"Источник силы", {"Добудьте в Даларане 6 |4треснувший сердечник:треснувших сердечника:треснувших сердечников; часового и принесите их доктору Мартину Фелбену в Подгород."}},
[96994] = {"Ваш первый верховой волк", {"Осмотрите верховых волков и выберите свое первое средство передвижения."}},
[96997] = {"Мертвый конь живее живого", {"Осмотрите коней-нежить и выберите свое первое средство передвижения."}},
[97003] = {"Чол'арук Стервятник", {"Принесите голову Чол'арука Гур'аку в Степях."}},
[97005] = {"Чол'арук Стервятник", {"Принесите голову Чол'арука Бэйнхему в Степях."}},
[97022] = {"Доклад Даните", {"Поговорите с Данитой Морр в крепости Бандариона."}},
[97047] = {"Кок в клетке", {"Найдите ключ от клетки Вендела и маскировку, которая позволит ему ускользнуть, в лагере Курцена."}},
[97048] = {"Возвращение в порт", {"Поговорите с капитаном Аранзас в Пиратской Бухте."}},
[97065] = {"На чаше весов – рыба-ангел Кифера", nil},
[97067] = {"На чаше весов – дезийская ставрида", nil},
[97074] = {"Уроки верховой езды", {"Станьте учеником в деле верховой езды с помощью Джартсама."}},
[97130] = {"Тайны древней империи Гурубаши", {"Достаньте идола древней империи Гурубаши из затонувшего города."}},
[97196] = {"Око Хладовея", {"Раздобудьте Око Хладовея в курганах Иглошкурых."}},
[97197] = {"Фрагмент Огненных Просторов", {"Раздобудьте в Глубинах Черной горы фрагмент Огненных Просторов для Алааны Штормовой Полет в Мулгоре."}},
[97198] = {"Магия Черночревов", {"Раздобудьте в логове Черночревов ритуальный тотем Черночревов."}},
[97200] = {"Уроки верховой езды", nil},
[97203] = {"Уроки верховой езды", {"Станьте учеником в деле верховой езды с помощью Вельмы Варнам."}},
[97220] = {"Просьба Филмора", {"Отнесите декларируемый груз к входу в хранилище. Оно находится в магазине \"Сыры Триаса\" в Торговом квартале."}},
[97222] = {"Товары из вестибюля", {"Отнесите декларируемый груз на верхний этаж магазина Триаса и поставьте его перед дверью."}},
[97223] = {"Матриарх кровопалых", {"Принесите яйца кровопалого матриарха Ксар'Ти в деревню Сен'джин."}},
[97225] = {"Забытые идолы лоа", {"Добудьте 8 |4забытого идола:забытых идолов:забытых идолов; лоа на островах Эха и принесите их мастеру Гадрину в деревню Сен'джин."}},
[97234] = {"Место для чтения", {"Отнесите завернутую литературу в библиотеку Штормграда."}},
[97236] = {"Клык Гитьис", {"Отнесите клык Гитьис тому, кто занимается изучением пауков в Альдрассиле."}},
[97237] = {"Прямо с полки", {"Найдите все нужные книги, находящиеся где-то в библиотеке, а затем вернитесь к Рою Льюэлсу в парк Штормграда."}},
[97242] = {"Сюрприз Йелмака", {"Соберите камыш и копье-траву, растущие у воды на Аллее Чести, и вернитесь к Кор'гельду в магазин \"Алхимия и эликсиры Йелмака\"."}},
[97243] = {"Зов Огня", {"Принесите факел спящего пламени Олариану Быстрая Вспышка в святилище пламени в Ветроягодных низинах."}},
[97244] = {"Зов Огня", {"Убейте жреца небес Фаладиэля в Ветроягодных низинах и заберите сердце Фаладиэля."}},
[97245] = {"Зов Огня", {"Отыщите дом Курамыы на Шен'дарском нагорье и одолейте духа в бою. Одержав победу, принесите его маску Олариану Быстрая Вспышка в Ветроягодных низинах."}},
[97246] = {"Обед по расписанию", {"Зайдите в \"Жаровню Борстана\" и скажите, что Татог попросил вас лично отнести Миги его обед."}},
[97249] = {"Любимая еда", {"Отнесите Миги его обед за крепость Громмаш."}},
[97250] = {"Ложное обвинение, очищенное имя", {"Убейте солдат Альянса, хозяйничающих на границе Степей и Пылевых топей, а затем возвращайтесь к рубаке Логмару в Лагерь Таурахо."}},
[97253] = {"Запчасти и детали", {"Соберите 5 |4горсть:горсти:горстей; изощренных деталей в верхнем лагере пиратов к югу от Кабестана, а затем вернитесь к Рениксу Презренному в Кабестан."}},
[97257] = {"Зов Огня", {"Подождите, пока Олариан проводит ритуал у жаровни подношений, и следуйте его указаниям.","","Вам нужно будет доставить Вечное пламя в Валанаар до того, как истечет выделенное время."}},
[97263] = {"Посылка прибыла", {"Доставьте потерянную посылку Элдруну."}},
[97265] = {"Ненависть к Ярой Ненависти", {"Победите разнообразных сатиров из племени Ярой Ненависти в Саргероне в Пустошах, а затем вернитесь к Ака'раю в деревню Ночных Охотников."}},
[97275] = {"Вуут-торопыга", {"Отнесите зелье Йелмака Вууту."}},
[97277] = {"Грунд и Гозвин", {"Найдите лагерь Грунда и Гозвина на северо-западных холмах. Заберите журнал механика Гозвина и убейте снежного леопарда – охотника."}},
[97279] = {"Брошенное оружие", {"Добудьте 6 |4комплект:комплекта:комплектов; брошенного тренировочного оружия и вернитесь к Кзану Шипорубу в Логово."}},
[97281] = {"Назревающая буря", {"Принесите тусклую сферу бури Резлаку, которого можно найти неподалеку от Сухой лощины."}},
[97282] = {"Бурный потенциал", {"Принесите 5 |4заряженный орган:заряженных органа:заряженных органов; рокочущей ящерицы Резлаку, которого можно найти неподалеку от Сухой лощины."}},
[97284] = {"Отмщение Валлариеля", {"Убейте орков из племени Пылающего Клинка в крепости Громового Топора в Пустошах, а затем вернитесь к Валлариелю Истребителю Демонов на Высоту Найджела."}},
[97286] = {"Доступ к исследованиям", nil},
[97287] = {"Хитрые переговоры", {"Поговорите с проекцией верховного мага Модеры рядом с Далараном."}},
[97288] = {"Неизбывные мучения", {"Принесите чудовищную голову мастеру аптекарю Фаранеллу в Подгород."}},
[97289] = {"Неизбывные мучения", {"Принесите голову барона к телу Отмара в Подгород."}},
[97290] = {"Неизбывные мучения", {"Расскажите мастеру аптекарю Фаранеллу в Подгороде о том, что вы узнали."}},
[97291] = {"Неизбывные мучения", {"Добудьте ядовитую черепоганку у Шатенн Гризетт в Торговом квартале, жгуч-траву у наставника травничества и субстанцию агонии у торговца ядами в квартале Разбойников и принесите ингредиенты мастеру аптекарю Фаранеллу в Подгород."}},
[97292] = {"Неизбывные мучения", {"Введите шипящую сыворотку в механизм над туловищем Отмара по просьбе мастера аптекаря Фаранелла."}},
[97326] = {"Камни для отдыха", {"Отнесите 8 |4гладкий валун:гладких валуна:гладких валунов; Тра за крепость Громмаш."}},
[97327] = {"Кошели Черночревов", {"Проникните в логово Черночревов, соберите 5 |4кошель:кошеля:кошелей; Черночревов и принесите Эккалю в руины Эльдарата, что в Азшаре."}},
[97328] = {"Что-нибудь ценное", {"Добудьте 8 |4ящик:ящика:ящиков; украденного груза в руинах Зул'Кунды в Тернистой долине и отнесите кому-нибудь в Пиратскую Бухту."}},
[97329] = {"Где ключ?", {"Добудьте примитивный ключ у троллей в руинах Зул'кунды в Тернистой долине и отнесите его Зиммиксу Искропыху."}},
[97331] = {"Великий побег Зиммикса", {"Проводите Зиммикса Искропыха подальше от руин Зул'Кунды, а затем расскажите о том, что спасли его, управляющему пристанью Подгребаю."}},
[97332] = {"Дважды обманутое ожидание", {"Доставьте дважды перезаказанную посылку управляющему пристанью Просвистуну в Пороховой порт в Лесоречье."}},
[97378] = {"Зеркальная Чешуя", {"Принесите крыло Зеркальной Чешуи Мелору Каменное Копыто в Громовой Утес."}},
[97386] = {"Расплата за Гром'гол", {"Командир Агро'гош из лагеря Гром'гол поручил вам убить огров на холме Мош'Огг."}},
[97405] = {"Жалобы на шум", {"Убейте 3 |4чаротвора:чаротворов:чаротворов;, 3 |4солдата-наемника:солдат-наемников:солдат-наемников;, 3 |4изверга:извергов:извергов; и 3 |4шамана:шаманов:шаманов; из клана Мош'Огг на холме Мош'Огг."}},
[97420] = {"Экономия, переработка и примирение", {"Добудьте 4 |4бочку:бочки:бочек; неочищенной нефти в лагере Торговой Компании на озере Назферити и отнесите Гназу Огнепыху в Тернистую долину."}},
[97453] = {"Борьба с сорняками", {"Уничтожьте 6 |4хищний сорняк:хищных сорняка:хищных сорняков; к югу от Гром'гола, а затем расскажите об этом матери Геммила."}},
[97485] = {"Традиции Утеса", {"Купите связку трав у травницы Ниды, связку сухих кедровых прутьев у торговки товарами для зачаровывателей Наты, жильную нить у продавца товаров для кожевников Маху, а также кремень и трут для церемоний у Наала, торгующего товарами для кулинаров.","","Совместите предметы и развейте получившиеся благовония на Вершине охотников."}},
[97490] = {"Остановить град", {"Найдите великана по имени Злобоград в южных холмах Зимних Ключей и соберите растущий на нем морозный мох."}},
[97530] = {"Пошлина Песчаного Молота", {"Начальник отдела безопасности Чепухастер из порта Картеля в Танарисе просит найти особенно блестящий браслет, потерянный возле поселения Песчаного Молота."}},
[97534] = {"Пыльное дело", {"Принесите 7 |4кусок:куска:кусков; пустынного хлама Квинн в Прибамбасск."}},
[97536] = {"Гномий мусор", {"Джорди Пепелатс хочет, чтобы вы опустошили контейнер радиоактивных отходов в пустыне Танарис на безопасном расстоянии от Прибамбасска и другого мусора, а затем вернулись к нему."}},
[97538] = {"Пигменты для красок", {"Тах Заиндевевшее Копыто в Громовом Утесе просит собрать для него 30 |4стручок:стручка:стручков; лихолиста на Мутном озере."}},
[97539] = {"Шелк для швов", {"Принесите 12 мотков хирургического паучьего шелка доктору Грегори Виктору в Павший Молот на Нагорье Арати."}},
[97558] = {"Шкуры для Отрекшихся", {"Принесите Шелене Робарт 8 |4мембрану:мембраны:мембран; крыла сумеречницы, 6 |4шкуру:шкуры:шкур; пса тьмы и 3 |4кусок:куска:кусков; кожи мурлока из племени Злобного Плавника."}},
[97583] = {"ВИХЛЯ", {"Купите немного питательной слизи и вернитесь к дружелюбному жизнерадостному слизнюку. Если он выглядит уставшим, попробуйте снова потанцевать с ним, чтобы привлечь его внимание."}},
[97617] = {"Проверка на безопасность", {"Добудьте 8 |4неизученный артефакт:неизученных артефакта:неизученных артефактов;, шахтерскую каску Лиги Исследователей и нетронутую мотыгу, а затем отнесите Горгарону на границу между Лок Моданом и Бесплодными землями."}},
[97663] = {"Припасы и исследования", {"Убейте огров в Знойных Песках, заберите у них украденные припасы и сделайте с их помощью оттиск с камней с письменами, а затем вернитесь к Мус'хале в Каргат."}},
