[98065] = {"Корона земли", {"Принесите частицы Лунного колодца Тиранде Шелест Ветра в храм Луны в Дарнассе."}},
[98067] = {"Глаза часовых", {"Разместите сов-часовых возле входа в глубины крепости Кенария, дарнасского банка, таверны на Террасе Ремесленников и городских ворот по просьбе часового Далии Солнечный Клинок из храма Луны в Дарнасе."}},
[98069] = {"Украденные припасы Вольного Ветра", {"Принесите 8 ящиков с украденными припасами Вольного Ветра Джандии на заставу Вольного Ветра."}},
[98070] = {"Довольно визгов", {"Убейте 5 |4визгливую гарпию:визгливых гарпий:визгливых гарпий;, 5 |4визгливую бродяжницу:визгливых бродяжниц:визгливых бродяжниц; и 5 |4визгливую призывательницу:визгливых призывательниц:визгливых призывательниц; ветров."}},
[98071] = {"Промысел пивовара", {"Отнесите бутылки с фолрукским сортовым вином в Дун Гарок в юго-восточной части предгорий Хилсбрада и принесите назад мешок их домашнего хмеля."}},
[98072] = {"Кроколиски в небесах", {"Принесите 8 безупречных алых чешуек Джеймсу Халлорану в Гавань Менетилов."}},
[98093] = {"Полевая зачистка", {"Убейте 7 |4грозового ящера:грозовых ящеров:грозовых ящеров; и 7 |4многозубого ловца:многозубых ловцов:многозубых ловцов; вокруг, чтобы Сулхаса смогла спуститься с дерева."}},
[98094] = {"Помощь разведчикам", {"Верховный палач Дарталия хочет, чтобы вы доставили новые указания стражу смерти Масоджу на юг от Мельницы Таррен, рядом с Дун Гароком."}},
[98095] = {"Ценные точки", {"Страж смерти Масодж хочет, чтобы вы разместили три аптекарских флакона на возвышенностях в предгорьях Хилсбрада и вернулись к нему."}},
[98155] = {"Безупречные шкуры паршивых гиен", {"Принесите 5 |4безупречную шкуру паршивой гиены:безупречные шкуры паршивых гиен:безупречных шкур паршивых гиен; Кристи Грант."}},
[98156] = {"Посылка с безупречными шкурами", {"Принесите посылку с безупречными шкурами Кимберли Грант."}},
[98189] = {"Возвращение статуэтки", {"Отнесите статуэтку Менетила капитану Крепкому Кулаку в крепость Менетилов."}},
[98190] = {"Друг семьи", {"Отнесите статуэтку Менетила верховному лорду Болвару Фордрагону в крепость Штормграда."}},
[98191] = {"Друг семьи", {"Отнесите статуэтку Менетила лорду Грейсону Тенелому в Собор Света."}},
[98192] = {"Сдирай кожу аккуратно, но сильно", {"Принесите 8 |4невредимую шкуру:невредимые шкуры:невредимых шкур; ящера Краку в деревню Гиблотопь."}},
[98197] = {"Трофеи войны", {"Добудьте для Валстага Сталезуба 6 ед. каз-моданской древесины и 30 ед. каз-моданского железа в Гавани Менетилов."}},
[98203] = {"Знахарь Ти'ик", {"Убейте знахаря из племени Сухокожих, известного как Ти'ик, в пещере к западу от Хири'ваты и вернитесь с его головой."}},
[98205] = {"Несносные дракончики!", {"Убейте 8 |4опаляющего малыша:опаляющих малышей:опаляющих малышей; дракона и 8 |4опаляющего дракончика:опаляющих дракончиков:опаляющих дракончиков;."}},
[98208] = {"Небесный цветок", {"Добудьте Норд'эль для Силессы Шепот Сумрака в Гавани Менетилов."}},
[98209] = {"Небесный цветок", {"Отнесите Норд'эль Тандрису Ветропряду в Аубердин на Темных берегах.","","Кажется, Силесса упоминала, что туда можно добраться на корабле из Гавани Менетилов."}},
[98215] = {"Чешуя для подпаленного хвоста", {"Принесите 20 |4сброшенную чешуйку:сброшенные чешуйки:сброшенных чешуек; темного дракона Драззиту Кранотеку."}},
[98216] = {"Понимание настоящего", {"Используйте камень Гоаз вблизи хранителя Гоаз и принесите его ключ-камень титанов геологу Вельгару."}},
[98219] = {"Опозоренный лейтенант", {"Поговорите с лейтенантом Фарреном Оринелем в Южнобережье в предгорьях Хилсбрада."}},
[98221] = {"Из пепла", {"Уничтожьте 4 комплекта планов нападения в лагере Злого Клыка по просьбе капитана Крепкий Кулак из крепости Менетилов."}},
[98223] = {"Старые привычки", {"Отнесите изодранную книгу заклинаний капитану Крепкому Кулаку в Гавань Менетилов."}},
[98230] = {"Эта земля принадлежала им", {"Идите по дороге и отыщите Ховина Мягкое Перо к востоку от Гавани Менетилов."}},
[98231] = {"Активный ингредиент", {"Принесите Гиззиксу Грязебульку 10 |4порцию:порции:порций; змейкиного хвоста."}},
[98233] = {"Меч в слизнюке", {"Верните стражу Джеймсону его учебный меч."}},
[98240] = {"Доставка багровых ящиков", {"Отнесите багровый ящик Ховину Мягкое Перо, который находится к востоку от Гавани Менетилов."}},
[98245] = {"Иголки из острых зубов", {"Добудьте 10 |4резец:резца:резцов; острозуба для Ховина Мягкое Перо."}},
[98246] = {"Непростые времена", {"Добудьте 12 |4идеальное яйцо:идеальных яйца:идеальных яиц; острозуба для Ховина Мягкое Перо."}},
[98247] = {"Транспортная этикетка", {"Доставьте транспортную этикетку кому-нибудь в \"Азеротском торговом управлении\" в Красногорье."}},
[98248] = {"Транспортная этикетка", {"Доставьте транспортную этикетку кому-нибудь на торговом посту \"Дуротарского снабжения и логистики\" рядом с Перекрестком в Степях."}},
[98251] = {"Больше ни ногой", {"Убейте 6 |4тенерога:тенерогов:тенерогов; и 6 |4медведя:медведей:медведей; Ясеневого леса, а затем вернитесь к Ва'загу Пламегневу к северо-западу от озера Зеркало Небес."}},
[98252] = {"Путь через пустоту", {"Покажите призванному Ва'загом оку Килрогга путь на главную дорогу Ясеневого леса."}},
[98282] = {"Опасная алхимия", {"Добудьте нелопнувшую железу хищника в пещере Тельгена для Кейтлин Грассман в Гавани Менетилов."}},
[98283] = {"Резчик-по-живому", {"Вернитесь с головой Резуна к Ретилю Стражу Природы в Зеленый Пояс."}},
[98285] = {"Основы походной жизни: инженерное дело", {"Поговорите со странным отшельником в Теневейном лесу, чтобы показать свои навыки и научиться создавать предмет для лагеря, соответствующий вашей профессии."}},
[98286] = {"Основы походной жизни: наложение чар", {"Поговорите с Насаланной Певицей Ветра в деревне Шен'дар, чтобы научиться создавать предмет для лагеря из вашей профессии, когда продемонстрируете свои навыки в ней."}},
[98291] = {"Гибель Драконьей Пасти!", {"Убейте 8 |4завоевателя:завоевателей:завоевателей;, 5 |4душеплета:душеплетов:душеплетов; и 3 |4лазутчика:лазутчиков:лазутчиков; из клана Драконьей Пасти в Убежище Драконьей Пасти для Ховина Мягкое Перо."}},
[98293] = {"Принудительное разоружение", {"Соберите 30 ед. снаряжения Драконьей Пасти в Убежище Драконьей Пасти, а затем отнесите его капитану Крепкому Кулаку в крепость Менетилов."}},
[98297] = {"Остановка цикла", {"Убейте подчиненного драконоида у врат Драконьей Пасти по просьбе Ховина Мягкое Перо."}},
[98298] = {"Безрассудство Аругала", {"Принесите 6 |4ошметок:ошметка:ошметков; воргена Далару Ткачу Рассвета в Гробницу."}},
[98299] = {"Остановить заражение", {"Убейте 5 |4больного беженца:больных беженцев:больных беженцев; и 5 |4изможденного беженца:изможденных беженцев:изможденных беженцев; по просьбе Далара Ткача Рассвета в Гробнице."}},
[98300] = {"Послание в Стальгорн", {"Доставьте послание от Ховина королю Магни Бронзобороду."}},
[98310] = {"Предвидение будущего", {"Используйте камень Гоаз рядом с Адосом, Модром, Голмом и Неру и принесите их сердца геологу Вельгару."}},
[98313] = {"Для дальнейшего изучения", {"Отнесите коллекцию реликвий Вельгара историку Карнику в Стальгорн."}},
[98319] = {"Зачистка горы", {"Разыщите горного пехотинца Корнелия в Серой берлоге по просьбе горного пехотинца Гретхен."}},
[98321] = {"Груз Огнива", {"Добудьте 8 |4груз:груза:грузов; Огнива из Серой берлоги для Тогнуса Огниво в Караносе."}},
[98322] = {"Зачистка горы", {"Встретьтесь с горным пехотинцем Гретхен к западу от Караноса."}},
[98323] = {"Зачистка горы", {"Вернитесь с отчетом горного пехотинца Гретхен к Сениру Белобороду в Каранос."}},
[98326] = {"Ледяной Вой", {"Убейте Ледяного Воя и верните мешок рыбы Гретте Гантер в поселке Пивоваров."}},
[98340] = {"Дух Великой Кошки", {"Поговорите с Дендритом Блеском Звезд в селении Ночная Гавань на Лунной поляне."}},
[98341] = {"Дух великой рожденной ветром кошки", {"Разыщите аватару Сэйлинан в южной части Лунной поляны и узнайте, чему она хочет научить вас касательно природы рожденной ветром кошки."}},
[98342] = {"Дух Великой Кошки", {"Добудьте реликвию клыка, реликвию когтя и реликвию тихой тени в кельях Малфуриона, а затем отнесите их духу Великой Кошки."}},
[98362] = {"К Громовому Утесу", {"Вернитесь в Громовой Утес и поговорите с Тюраком Руническим Тотемом на Вершине Старейшин."}},
[98372] = {"Бесславная участь", nil},
[98386] = {"Лесопилка Альтера", {"Убейте 12 |4крупного тарантула:крупных тарантулов:крупных тарантулов; и уничтожьте 6 |4яйцо:яйца:яиц; тарантулов на лесопилке Альтера по просьбе штейгера Ослоу, который находится в Красногорье."}},
[98387] = {"Блокада Черной Горы", {"Принесите 8 ед. украденного оружия и 10 |4ящик:ящика:ящиков; с украденными припасами маршалу Маррису в Приозерье."}},
[98389] = {"Свет во тьме", {"Освободите 6 |4жертву:жертвы:жертв; в паутине в низине Ночных Пут по просьбе Арамиса Хаммерхенда, находящегося в Похоронном Звоне."}},
[98391] = {"Сестринство Элуны", {"Поговорите с сестрой Аквинной в Дарнассе."}},
[98392] = {"Тьма на поляне", {"Принесите амулет злобного визга, амулет повелительницы ветра Гаэдрессы и амулет матери-ведьмы Арисы часовому Арании Проблеск Солнца на Поляну Оракула."}},
[98393] = {"Дух Великой Кошки", {"Поговорите с Дендритом Блеском Звезд в селении Ночная Гавань на Лунной поляне."}},
[98394] = {"Дух Великой Кошки", {"Найдите духа Великой Кошки в южной части Лунной поляны и усвойте все, что он расскажет вам о природе кошки."}},
[98396] = {"Дух Великой Кошки", {"Добудьте реликвию клыка, реликвию когтя и реликвию тихой тени в кельях Малфуриона, а затем отнесите их духу Великой Кошки."}},
[98397] = {"В Дарнас", {"Вернитесь в Дарнас и поговорите с Матренгилом Медвежья Лапа в анклаве Кенария."}},
[98398] = {"Древо-оракул", {"Найдите находящуюся неподалеку кору Древа-оракула, чтобы получить его послание."}},
[98403] = {"Извращенная ненависть", {"Убейте 8 |4оскверненного чащобного тенетника:оскверненных чащобных тенетников:оскверненных чащобных тенетников;, а также добудьте зрелый мох Скверны у Зеторра Злобного и принесите его Таллонкаю Гибкий Корень в Доланаар."}},
[98404] = {"Дух великой рожденной ветром кошки", {"Добудьте реликвию клыка, реликвию когтя и реликвию тихой тени в кельях Малфуриона, а затем отнесите их аватаре Сэйлинана."}},
[98405] = {"Дух Великой Кошки", {"Найдите духа Великой Кошки в южной части Лунной поляны и усвойте все, что он расскажет вам о природе кошки."}},
[98407] = {"Демонстрация силы", {"Добудьте 5 |4шипастый ошейник:шипастых ошейника:шипастых ошейников; у твердозубов из стаи Красногорья для заместителя судьи Фелдона, который находится недалеко от Приозерья."}},
[98417] = {"Путь мщения", {"Масейра Осенняя Луна просит вас осмотреть местность к западу от Лесной Песни, где водятся демоны Сатирнаара. Принесите ей любые сведения о ее муже Куротеле."}},
[98418] = {"Общая ярость", {"Убейте 5 |4разбойника:разбойников:разбойников;, 5 |4скверноподданного:скверноподданных:скверноподданных;, 5 |4предателя:предателей:предателей; и 5 |4призывателя:призывателей:призывателей; огня из племени Ксавиан.","После этого вернитесь к Масейре Осенняя Луна в Лесную Песнь."}},
[98423] = {"Соглашение о взаимопонимании", {"Доставьте Договор о взаимопонимании Магни Бронзобороду в Стальгорн."}},
[98424] = {"Заметки Шумовика", {"Соберите оставшиеся страницы записей бригадира Шумовика в шахте Торговой Компании и отнесите их Морину Ловцу Облаков, которого можно найти неподалеку от деревни Кровавого Копыта."}},
[98427] = {"Прекращение работ", {"Отнесите ключ от лесопила Морину Ловцу Облаков возле деревни Кровавого Копыта."}},
[98430] = {"Дальноходы", {"Помогите Периту Штормовое Копыто сбежать с утеса Бледногривов и сообщите о том, что он в безопасности, Кэрну Кровавое Копыто в Громовом Утесе."}},
[98435] = {"Донесение Громового Рога", {"Принесите донесение Громового Рога верховному друиду Хамуулу Руническому Тотему в Громовой Утес."}},
[98459] = {"Дефицит чести", {"Доставьте подарок Тома Барту Приливню в Гавань Менетилов в Болотине."}},
[98461] = {"Безответная любовь", {"Отнесите записку Холли Таррелу Камнепряду, живущему неподалеку от Гавани Менетилов в Болотине."}},
[98462] = {"Покров зимних пустошей", nil},
[98463] = {"Предмет сплетен", {"Поговорите с Никсразом Наливайкой в таверне \"Старый моряк\" в Пиратской Бухте, что в Тернистой долине."}},
[98477] = {"Нестабильная магия", {"Принесите 10 |4частицу:частицы:частиц; нестабильной магии Нуаре Сотрясающее Копыто."}},
[98512] = {"Ал'акетские убийцы", {"Устраните 10 ал'акетских убийц на Шен'дарском нагорье."}},
[98545] = {"Письмо Леонида", {"Отнесите запечатанное письмо Гликсу Ксиззиксу в Подгород."}},
[98574] = {"Освященный меморандум", {"Изучите освященный меморандум, а затем найдите в Старой Наковальне Бранстока Халдера и поговорите с ним."}},
[98575] = {"Оскверненная скрижаль", {"Прочтите, что написано на оскверненной скрижали, и поговорите с Нартоком в Логове в Долине Испытаний."}},
[98576] = {"Покрытый письменами пергамент", {"Прочтите покрытый письменами пергамент и поговорите с Май'ах у входа в Логово в долине Испытаний."}},
[98581] = {"Архаичная руна", {"Прочтите архаичную руну и поговорите с Тео Громовым Молотом в Старой Наковальне."}},
[98601] = {"Трудный путь", {"Прочитайте освященный свиток и поговорите с Арамисом Хаммерхендом в церкви Похоронного Звона."}},
[98731] = {"Благословение духа Великой Кошки", {"Найдите духа Великого Медведя на северо-западе Лунной поляны и усвойте все, что он расскажет вам о природе медведя. Когда уроки будут закончены, вернитесь к Дендриту Блеску Звезд в Ночную Гавань в Лунной поляне."}},
[98738] = {"Благословение духа Великой Рожденной Ветром Кошки", {"Найдите духа Великого Медведя на северо-западе Лунной поляны и усвойте все, что он расскажет вам о природе медведя. Когда уроки будут закончены, вернитесь к Дендриту Блеску Звезд в Ночную Гавань в Лунной поляне."}},
[98739] = {"Благословение духа Великой Кошки", {"Поговорите с Дендритом."}},
[98815] = {"Шкуры нагорья", {"Отнесите 4 |4шкуру:шкуры:шкур; чащобного ящера кожевнику Джеймсу Халлорану в Гавань Менетилов."}},
[98823] = {"Земной отголосок", {"Отнесите реликвию титанов Мулну Гнев Земли на Плато звездочетов на северо-западе Мулгора."}},
[98824] = {"Доисторическая призма", {"Отнесите реликвию титанов старшему исследователю Магелласу в Зал Исследователей в Стальгорне."}},
[98887] = {"Борьба за острова Черного Копья", {"Принесите 3 почетных знака островов Черного Копья ордынскому вестнику войны у входа на поля боя."}},
[98895] = {"Стычка на островах Черного Копья", {"Принесите 3 почетных знака островов Черного Копья бригадному генералу Альянса рядом со входом на поля боя."}},
[98903] = {"Битва за острова Черного Копья!", nil},
